# Peloton Workout Integration
import requests

PELOTON_USERNAME = "handleDesktopRelaySocketReadyRead"
PELOTON_PASSWORD = "your_password"

def get_peloton_workouts():
    """Get recent Peloton workouts"""
    # Login to get session
    session = requests.Session()
    login = session.post(
        "https://api.onepeloton.com/auth/login",
        json={"username_or_email": PELOTON_USERNAME, "password": PELOTON_PASSWORD}
    )

    # Get workouts
    response = session.get(
        "https://api.onepeloton.com/api/user/me/workouts",
        params={"limit": 10}
    )
    return response.json()

def get_workout_details(workout_id):
    """Get detailed workout performance"""
    response = session.get(
        f"https://api.onepeloton.com/api/workout/{workout_id}/performance_graph"
    )
    return response.json()
